const TOTAL_FRAMES = 288; // 24fps × 12s
const CDN_BASE_URL = 'https://YOUR_PULL_ZONE.b-cdn.net/grcup/frames/trophy_frames_webp';
const WINDOW_SIZE = 60;   // 30 behind + 30 ahead (~480MB RAM max)
const MAX_FRAME_JUMP = 8; // prevents scroll outrunning cache
const PRELOAD_INITIAL = 60; // frames loaded before animation is unlocked

function frameUrl(index) {
  const padded = String(index + 1).padStart(4, '0');
  return `${CDN_BASE_URL}/frame_${padded}.webp`;
}

const cache = new Map();

function updateCache(currentFrame) {
  const start = Math.max(0, currentFrame - 30);
  const end = Math.min(TOTAL_FRAMES - 1, currentFrame + 30);

  // Evict frames outside window (~8MB freed per eviction)
  for (const [index] of cache) {
    if (index < start || index > end) {
      cache.delete(index);
    }
  }

  // Preload frames inside window
  for (let i = start; i <= end; i++) {
    if (!cache.has(i)) {
      const img = new Image();
      img.src = frameUrl(i);
      cache.set(i, img);
    }
  }
}

let displayedFrame = 0;
const canvas = document.querySelector('#trophy-canvas');
const ctx = canvas.getContext('2d');

function drawFrame(index) {
  const img = cache.get(index);
  if (img && img.complete) {
    ctx.drawImage(img, 0, 0, canvas.width, canvas.height);
  }
}

window.addEventListener('scroll', () => {
  const scrollable = document.body.scrollHeight - window.innerHeight;
  const progress = Math.min(window.scrollY / scrollable, 1);
  const targetFrame = Math.floor(progress * (TOTAL_FRAMES - 1));

  // Clamp jump — animation catches up smoothly, never teleports
  if (targetFrame > displayedFrame) {
    displayedFrame = Math.min(displayedFrame + MAX_FRAME_JUMP, targetFrame);
  } else {
    displayedFrame = Math.max(displayedFrame - MAX_FRAME_JUMP, targetFrame);
  }

  drawFrame(displayedFrame);
  updateCache(displayedFrame);
}, { passive: true });

let animationReady = false;

async function preloadInitialFrames() {
  const promises = [];
  for (let i = 0; i < PRELOAD_INITIAL; i++) {
    const img = new Image();
    img.src = frameUrl(i);
    cache.set(i, img);
    promises.push(new Promise(res => {
      img.onload = res;
      img.onerror = res; // don't block on failed frames
    }));
  }
  await Promise.all(promises);
  animationReady = true;
  // Remove loading overlay
  document.querySelector('#loading-overlay')?.remove();
}
